//! The Razer keyboard atlas: what openrazer, OpenRGB and SignalRGB send each Razer keyboard, per PID.
//!
//! The data lives in `protocol/razer-keyboards.toml` (regenerated by the testkit's `razer-atlas`
//! tool), one entry per PID with each source's values kept apart. This module weighs, per field,
//! how many independent lineages state each value: OpenRGB's Razer tables derive from openrazer,
//! so their agreement counts once. Synthesis reads the result as priors: which transaction ids to
//! probe first, which collection to try first, the matrix size a getter cannot reveal, and the LED
//! a keyboard's effects address. Probing still decides what a board answers; the atlas never turns
//! a guess into hardware evidence.

use serde::Deserialize;
use std::collections::BTreeMap;
use std::sync::OnceLock;

const ATLAS: &str = include_str!("../protocol/razer-keyboards.toml");
const MICE: &str = include_str!("../protocol/razer-mice.toml");

/// Which command class a source drives the keyboard's lighting through.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum Class {
    /// Class 0x0F, the matrix family.
    Extended,
    /// Class 0x03, the legacy family.
    Standard,
    /// One-row legacy boards (OpenRGB's linear type).
    Linear,
    /// Anything else OpenRGB names (ARGB, none, custom).
    #[serde(other)]
    Other,
}

#[derive(Clone, Debug, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct OpenRazer {
    pub class: Class,
    pub effect_tx: u8,
    pub getter_tx: Option<u8>,
    pub frame_tx: Option<u8>,
    pub rows: Option<u8>,
    pub cols: Option<u8>,
    /// USB interface (wIndex) the driver addresses.
    pub interface: u8,
    /// The driver's SET->GET wait for this PID, in µs.
    pub wait_us: Option<u32>,
    pub at: Option<String>,
}

#[derive(Clone, Debug, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct OpenRgb {
    pub class: Class,
    pub tx: u8,
    pub led: Option<u8>,
    pub rows: u8,
    pub cols: u8,
    pub interface: Option<u8>,
    pub usage_page: Option<u16>,
    pub usage: Option<u16>,
    /// Further detector collections, `[interface, usage_page, usage]`, for boards whose control
    /// collection moved between firmware revisions.
    #[serde(default)]
    pub also: Vec<[u16; 3]>,
    pub at: String,
    pub detect_at: Option<String>,
}

#[derive(Clone, Debug, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct SignalRgb {
    pub class: Option<Class>,
    /// The tx its custom-frame rows go out at.
    pub row_tx: Option<u8>,
    pub cols: Option<u8>,
    pub interface: Option<u8>,
    pub at: String,
}

#[derive(Clone, Debug, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Keyboard {
    pub pid: u16,
    pub name: String,
    /// `"laptop"` for a Blade or Book's built-in keyboard.
    pub form: Option<String>,
    pub openrazer: Option<OpenRazer>,
    pub openrgb: Option<OpenRgb>,
    pub signalrgb: Option<SignalRgb>,
}

/// What openrazer's mouse driver and daemon state for one mouse.
#[derive(Clone, Debug, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct OpenRazerMouse {
    pub rows: Option<u8>,
    pub cols: Option<u8>,
    /// USB interface (wIndex) the driver addresses.
    pub interface: u8,
    /// The driver's SET->GET wait for this PID, in µs.
    pub wait_us: Option<u32>,
    pub at: Option<String>,
}

#[derive(Clone, Debug, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Mouse {
    pub pid: u16,
    pub name: String,
    pub openrazer: Option<OpenRazerMouse>,
    pub openrgb: Option<OpenRgb>,
}

impl Mouse {
    /// The lighting matrix, `(rows, cols)`. OpenRGB derives from openrazer, so their agreement is
    /// one lineage.
    #[must_use]
    pub fn dims(&self) -> Sourced<(u8, u8)> {
        let or = self.openrazer.as_ref().and_then(|o| Some((o.rows?, o.cols?)));
        let rgb = self.openrgb.as_ref().map(|o| (o.rows, o.cols));
        Sourced::of([(or, Origin::OpenRazer), (rgb, Origin::OpenRgb)])
    }

    /// The tx OpenRGB drives the mouse at.
    #[must_use]
    pub fn tx(&self) -> Sourced<u8> {
        Sourced::of([(self.openrgb.as_ref().map(|o| o.tx), Origin::OpenRgb)])
    }

    /// openrazer's reply wait for this PID, in µs: 600 wired, longer behind most receivers.
    #[must_use]
    pub fn reply_wait_us(&self) -> Option<u32> {
        self.openrazer.as_ref()?.wait_us
    }
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct MiceFile {
    #[allow(dead_code)]
    sources: BTreeMap<String, Source>,
    mouse: Vec<Mouse>,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct Source {
    url: String,
    license: String,
    sha: String,
    /// The source whose tables this one's were taken from: agreement between them is one voice.
    derived_from: Option<String>,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct File {
    sources: BTreeMap<String, Source>,
    keyboard: Vec<Keyboard>,
}

/// Which source stated a value, in tie-break order: OpenRGB and SignalRGB drive these boards
/// through the same Windows HID feature reports neuron uses.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub enum Origin {
    OpenRgb,
    SignalRgb,
    OpenRazer,
}

impl Origin {
    const ALL: [Origin; 3] = [Origin::OpenRgb, Origin::SignalRgb, Origin::OpenRazer];

    #[must_use]
    pub fn name(self) -> &'static str {
        match self {
            Origin::OpenRazer => "openrazer",
            Origin::OpenRgb => "OpenRGB",
            Origin::SignalRgb => "SignalRGB",
        }
    }

    /// Its key in the atlas's `[sources]`.
    fn key(self) -> &'static str {
        match self {
            Origin::OpenRazer => "openrazer",
            Origin::OpenRgb => "openrgb",
            Origin::SignalRgb => "signalrgb",
        }
    }

    /// The source this one's tables derive from, followed to its root.
    #[must_use]
    pub fn lineage(self) -> Origin {
        let mut at = self;
        for _ in 0..Origin::ALL.len() {
            let parent = file()
                .and_then(|f| f.sources.get(at.key()))
                .and_then(|s| s.derived_from.as_deref())
                .and_then(|k| Origin::ALL.into_iter().find(|o| o.key() == k));
            match parent {
                Some(p) => at = p,
                None => break,
            }
        }
        at
    }
}

/// How well the preferred value is supported.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub enum Support {
    /// No source states it.
    None,
    /// One source states it.
    Single,
    /// Several sources state it, all from one lineage.
    Echoed,
    /// Sources from at least two independent lineages state it.
    Independent,
}

/// One field as the sources state it: each claim with its origin.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Sourced<T> {
    claims: Vec<(T, Origin)>,
}

impl<T: Copy + PartialEq> Sourced<T> {
    fn of(claims: impl IntoIterator<Item = (Option<T>, Origin)>) -> Self {
        Sourced { claims: claims.into_iter().filter_map(|(v, o)| Some((v?, o))).collect() }
    }

    fn origins(&self, v: T) -> Vec<Origin> {
        let mut out: Vec<Origin> = self.claims.iter().filter(|c| c.0 == v).map(|c| c.1).collect();
        out.sort_unstable();
        out
    }

    fn lineages(&self, v: T) -> usize {
        let mut roots: Vec<Origin> = self.origins(v).into_iter().map(Origin::lineage).collect();
        roots.sort_unstable();
        roots.dedup();
        roots.len()
    }

    /// Every distinct value stated, best supported first: more independent lineages win, and a
    /// tie goes to the value whose first source comes first in [`Origin`] order.
    #[must_use]
    pub fn candidates(&self) -> Vec<T> {
        let mut values: Vec<T> = Vec::new();
        for &(v, _) in &self.claims {
            if !values.contains(&v) {
                values.push(v);
            }
        }
        values.sort_by_key(|&v| (std::cmp::Reverse(self.lineages(v)), self.origins(v).first().copied()));
        values
    }

    /// The value to act on.
    #[must_use]
    pub fn preferred(&self) -> Option<T> {
        self.candidates().first().copied()
    }

    /// Whether the sources state more than one value.
    #[must_use]
    pub fn is_conflict(&self) -> bool {
        self.candidates().len() > 1
    }

    /// How well the preferred value is supported.
    #[must_use]
    pub fn support(&self) -> Support {
        let Some(v) = self.preferred() else { return Support::None };
        match (self.lineages(v), self.origins(v).len()) {
            (l, _) if l >= 2 => Support::Independent,
            (_, n) if n >= 2 => Support::Echoed,
            _ => Support::Single,
        }
    }

    /// A short provenance label for generated files and reports.
    #[must_use]
    pub fn grade(&self) -> String {
        let names = |os: Vec<Origin>| os.into_iter().map(Origin::name).collect::<Vec<_>>().join(", ");
        let Some(v) = self.preferred() else { return "no source".into() };
        let backing = names(self.origins(v));
        if self.is_conflict() {
            let others: Vec<Origin> = self.claims.iter().filter(|c| c.0 != v).map(|c| c.1).collect();
            return format!("sources disagree: {backing} over {}", names(others));
        }
        match self.support() {
            Support::Independent => format!("{backing} agree independently"),
            Support::Echoed => format!("{backing} agree, one lineage"),
            _ => format!("{backing} only"),
        }
    }
}

/// A HID collection a source opens for the control pipe.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Collection {
    pub interface: Option<u8>,
    pub usage_page: u16,
    pub usage: u16,
}

impl Keyboard {
    #[must_use]
    pub fn class(&self) -> Sourced<Class> {
        Sourced::of([
            (self.openrazer.as_ref().map(|o| o.class), Origin::OpenRazer),
            (self.openrgb.as_ref().map(|o| o.class), Origin::OpenRgb),
            (self.signalrgb.as_ref().and_then(|o| o.class), Origin::SignalRgb),
        ])
    }

    /// Matrix rows and columns. SignalRGB states columns only, so it backs whichever stated size
    /// has its column count.
    #[must_use]
    pub fn dims(&self) -> Sourced<(u8, u8)> {
        let or = self.openrazer.as_ref().and_then(|o| Some((o.rows?, o.cols?)));
        let rgb = self.openrgb.as_ref().map(|o| (o.rows, o.cols));
        let sig_cols = self.signalrgb.as_ref().and_then(|s| s.cols);
        let sig = sig_cols.and_then(|c| [rgb, or].into_iter().flatten().find(|d| d.1 == c));
        Sourced::of([(or, Origin::OpenRazer), (rgb, Origin::OpenRgb), (sig, Origin::SignalRgb)])
    }

    /// The tx each source sends lighting at: openrazer's effects, OpenRGB's one tx, SignalRGB's
    /// frame rows.
    #[must_use]
    pub fn lighting_tx(&self) -> Sourced<u8> {
        Sourced::of([
            (self.openrazer.as_ref().map(|o| o.effect_tx), Origin::OpenRazer),
            (self.openrgb.as_ref().map(|o| o.tx), Origin::OpenRgb),
            (self.signalrgb.as_ref().and_then(|o| o.row_tx), Origin::SignalRgb),
        ])
    }

    /// Every tx any source sends this board's lighting at, best supported first.
    #[must_use]
    pub fn tx_candidates(&self) -> Vec<u8> {
        let mut out = self.lighting_tx().candidates();
        if let Some(o) = &self.openrazer {
            for t in [o.getter_tx, o.frame_tx].into_iter().flatten() {
                if !out.contains(&t) {
                    out.push(t);
                }
            }
        }
        out
    }

    /// The LED effects and brightness address. Only OpenRGB names it per board; openrazer's
    /// keyboard builders use the backlight LED 0x05.
    #[must_use]
    pub fn led(&self) -> Sourced<u8> {
        Sourced::of([
            (self.openrazer.as_ref().map(|_| 0x05), Origin::OpenRazer),
            (self.openrgb.as_ref().and_then(|o| o.led), Origin::OpenRgb),
        ])
    }

    /// USB interface of the control collection.
    #[must_use]
    pub fn interface(&self) -> Sourced<u8> {
        Sourced::of([
            (self.openrazer.as_ref().map(|o| o.interface), Origin::OpenRazer),
            (self.openrgb.as_ref().and_then(|o| o.interface), Origin::OpenRgb),
            (self.signalrgb.as_ref().and_then(|o| o.interface), Origin::SignalRgb),
        ])
    }

    /// The collections OpenRGB opens, in its detector order.
    #[must_use]
    pub fn collections(&self) -> Vec<Collection> {
        let Some(o) = &self.openrgb else { return Vec::new() };
        let first = o
            .usage_page
            .zip(o.usage)
            .map(|(usage_page, usage)| Collection { interface: o.interface, usage_page, usage });
        let also = o
            .also
            .iter()
            .map(|&[i, usage_page, usage]| Collection { interface: u8::try_from(i).ok(), usage_page, usage });
        first.into_iter().chain(also).collect()
    }

    /// openrazer's reply wait for this PID, in µs. Razer keyboards enumerate a separate PID per
    /// link, so a wired PID's short wait and a wireless PID's long one both come from the table.
    #[must_use]
    pub fn reply_wait_us(&self) -> Option<u32> {
        self.openrazer.as_ref()?.wait_us
    }

    #[must_use]
    pub fn is_laptop(&self) -> bool {
        self.form.as_deref() == Some("laptop")
    }
}

fn file() -> Option<&'static File> {
    static F: OnceLock<Option<File>> = OnceLock::new();
    F.get_or_init(|| toml::from_str::<File>(ATLAS).ok()).as_ref()
}

/// Every keyboard in the atlas.
#[must_use]
pub fn keyboards() -> &'static [Keyboard] {
    file().map_or(&[], |f| f.keyboard.as_slice())
}

/// The atlas entry for a USB VID:PID. Only Razer keyboards are in it; any other vendor's PID, even
/// one that collides with a Razer PID, has no entry.
#[must_use]
pub fn lookup(vid: u16, pid: u16) -> Option<&'static Keyboard> {
    if vid != crate::dialect::RAZER_VID {
        return None;
    }
    keyboards().iter().find(|k| k.pid == pid)
}

/// Every mouse in the mouse atlas.
#[must_use]
pub fn mice() -> &'static [Mouse] {
    static F: OnceLock<Option<MiceFile>> = OnceLock::new();
    F.get_or_init(|| toml::from_str::<MiceFile>(MICE).ok()).as_ref().map_or(&[], |f| f.mouse.as_slice())
}

/// The mouse atlas entry for a USB VID:PID; Razer only.
#[must_use]
pub fn lookup_mouse(vid: u16, pid: u16) -> Option<&'static Mouse> {
    if vid != crate::dialect::RAZER_VID {
        return None;
    }
    mice().iter().find(|m| m.pid == pid)
}

/// The pinned source revisions, as `name@sha8 url (license)` for provenance lines.
#[must_use]
pub fn source_pins() -> Vec<String> {
    file()
        .map(|f| {
            f.sources
                .iter()
                .map(|(k, s)| format!("{k}@{} {} ({})", &s.sha[..s.sha.len().min(8)], s.url, s.license))
                .collect()
        })
        .unwrap_or_default()
}

#[cfg(test)]
mod tests {
    use super::*;

    const R: u16 = crate::dialect::RAZER_VID;

    #[test]
    fn the_mouse_atlas_parses_and_matches_the_desk() {
        let parsed: MiceFile = toml::from_str(MICE).unwrap_or_else(|e| panic!("razer-mice.toml does not parse: {e}"));
        assert!(parsed.mouse.len() > 100, "{}", parsed.mouse.len());
        assert_eq!(mice().len(), parsed.mouse.len());
        // The Naga V2 Pro on its receiver: tx 0x1F and a 31 ms wait, both live-verified on the desk.
        let naga = lookup_mouse(R, 0x00A8).expect("Naga V2 Pro receiver");
        assert_eq!(naga.tx().preferred(), Some(0x1F));
        assert_eq!(naga.reply_wait_us(), Some(31_000));
        assert_eq!(lookup_mouse(R, 0x007A).and_then(Mouse::reply_wait_us), Some(59_900), "a Viper receiver");
        assert_eq!(lookup_mouse(R, 0x0099).and_then(|m| m.dims().preferred()), Some((1, 11)), "Basilisk V3");
        assert!(lookup_mouse(0x046D, 0x00A8).is_none(), "another vendor's PID");
    }

    fn parse() -> File {
        toml::from_str(ATLAS).unwrap_or_else(|e| panic!("razer-keyboards.toml does not parse: {e}"))
    }

    #[test]
    fn the_atlas_parses_and_every_entry_is_sourced() {
        let f = parse();
        assert!(f.keyboard.len() > 100, "the atlas covers the sources' keyboards");
        let mut pids: Vec<u16> = f.keyboard.iter().map(|k| k.pid).collect();
        pids.sort_unstable();
        let n = pids.len();
        pids.dedup();
        assert_eq!(pids.len(), n, "one entry per PID");
        for k in &f.keyboard {
            assert!(k.openrazer.is_some() || k.openrgb.is_some(), "{:04x} names no source", k.pid);
            if let Some(o) = &k.openrazer {
                if let Some(at) = &o.at {
                    assert!(at.starts_with("daemon/") && at.contains("#L"), "{:04x}: {at}", k.pid);
                }
                assert_eq!(o.rows.is_some(), o.cols.is_some(), "{:04x}: rows without cols", k.pid);
            }
            if let Some(o) = &k.openrgb {
                assert!(o.at.starts_with("Controllers/RazerController/") && o.at.contains("#L"), "{:04x}", k.pid);
                assert_eq!(o.usage_page.is_some(), o.usage.is_some(), "{:04x}: page without usage", k.pid);
                assert!(o.also.iter().all(|c| c[0] <= 0xFF), "{:04x}: interface out of range", k.pid);
            }
            if let Some(s) = &k.signalrgb {
                assert!(s.at.starts_with("Plugins/Razer/"), "{:04x}: {}", k.pid, s.at);
            }
        }
        assert_eq!(keyboards().len(), n, "the runtime view loads the same file");
        assert!(f.keyboard.iter().filter(|k| k.signalrgb.is_some()).count() > 20, "SignalRGB is cross-referenced");
    }

    #[test]
    fn sources_are_pinned_licensed_and_lineaged() {
        let f = parse();
        for name in ["openrazer", "openrgb", "signalrgb"] {
            let s = f.sources.get(name).unwrap_or_else(|| panic!("source {name} missing"));
            assert_eq!(s.sha.len(), 40, "{name} sha is a full commit");
            assert!(s.sha.chars().all(|c| c.is_ascii_hexdigit()), "{name} sha is hex");
            assert!(s.url.starts_with("https://"), "{name} url");
            assert!(!s.license.is_empty(), "{name}: cite facts, never copy code");
        }
        assert_eq!(source_pins().len(), 3);
        assert_eq!(Origin::OpenRgb.lineage(), Origin::OpenRazer, "OpenRGB's Razer tables derive from openrazer");
        assert_eq!(Origin::SignalRgb.lineage(), Origin::SignalRgb);
        assert_eq!(Origin::OpenRazer.lineage(), Origin::OpenRazer);
    }

    #[test]
    fn one_lineage_counts_once() {
        let echoed = Sourced::of([(Some(1u8), Origin::OpenRazer), (Some(1), Origin::OpenRgb)]);
        assert_eq!(echoed.support(), Support::Echoed);
        let independent = Sourced::of([(Some(1u8), Origin::OpenRazer), (Some(1), Origin::SignalRgb)]);
        assert_eq!(independent.support(), Support::Independent);
        // Two derived voices against one independent one is a tie, broken by origin order.
        let tie = Sourced::of([(Some(1u8), Origin::OpenRazer), (Some(1), Origin::OpenRgb), (Some(2), Origin::SignalRgb)]);
        assert_eq!(tie.candidates(), vec![1, 2]);
        // An independent second voice outweighs OpenRGB's tie-break.
        let outvoted = Sourced::of([(Some(1u8), Origin::OpenRazer), (Some(2), Origin::OpenRgb), (Some(1), Origin::SignalRgb)]);
        assert_eq!(outvoted.preferred(), Some(1));
        assert!(outvoted.grade().starts_with("sources disagree: SignalRGB, openrazer over OpenRGB"), "{}", outvoted.grade());
        assert_eq!(Sourced::<u8>::of([]).preferred(), None);
        assert_eq!(Sourced::<u8>::of([]).support(), Support::None);
    }

    /// Literals read by hand from the pinned sources, not from this file: openrazer
    /// razerkbd_driver.c L4375-4382 (V3 brightness read at 0x3F), the static group (V3 and V4 X
    /// at 0x3F), razer_get_report_params (V3 wIndex 3, V4 X wIndex 2); OpenRGB RazerDevices.cpp
    /// (V3 0x3F, V4 X 0x1F, both LED 0x05, 6x22) and RazerControllerDetect.cpp (V3 MI 3 0x0C/0x01,
    /// V4 X MI 2 0x01/0x02); SignalRGB Razer_Blackwidow_V3_Keyboard.js (rows at 0x3F, 0x47 bytes,
    /// interface 3).
    #[test]
    fn hand_checked_entries_match_their_sources() {
        assert!(lookup(0x046D, 0x024E).is_none(), "another vendor's colliding PID is not a Razer keyboard");
        let v3 = lookup(R, 0x024E).expect("BlackWidow V3");
        assert_eq!(v3.class().preferred(), Some(Class::Extended));
        assert_eq!(v3.class().support(), Support::Independent);
        assert_eq!(v3.lighting_tx().candidates(), vec![0x3F]);
        assert_eq!(v3.lighting_tx().support(), Support::Independent);
        assert_eq!(v3.tx_candidates(), vec![0x3F, 0x1F], "rows go out at 0x1F in openrazer");
        assert_eq!(v3.dims().candidates(), vec![(6, 22)]);
        assert_eq!(v3.interface().candidates(), vec![3]);
        assert_eq!(v3.collections(), vec![Collection { interface: Some(3), usage_page: 0x000C, usage: 0x0001 }]);
        assert_eq!(v3.led().candidates(), vec![0x05]);

        let v4x = lookup(R, 0x0293).expect("BlackWidow V4 X");
        assert!(v4x.lighting_tx().is_conflict());
        assert_eq!(v4x.lighting_tx().preferred(), Some(0x1F));
        assert_eq!(v4x.tx_candidates(), vec![0x1F, 0x3F]);
        assert_eq!(v4x.interface().candidates(), vec![2]);
        assert_eq!(v4x.collections()[0], Collection { interface: Some(2), usage_page: 0x0001, usage: 0x0002 });

        let chroma_v2 = lookup(R, 0x0221).expect("BlackWidow Chroma V2");
        assert_eq!(chroma_v2.class().preferred(), Some(Class::Standard));
        assert_eq!(chroma_v2.lighting_tx().preferred(), Some(0x3F), "the live-proven lighting tx");
        assert_eq!(chroma_v2.dims().preferred(), Some((6, 22)));
    }

    #[test]
    fn disagreements_stay_visible() {
        let v4_75 = lookup(R, 0x02A5).expect("BlackWidow V4 75%");
        assert_eq!(v4_75.dims().candidates(), vec![(6, 18), (6, 16)]);
        assert!(v4_75.dims().grade().contains("disagree"));
        let ds = lookup(R, 0x0292).expect("DeathStalker V2 Pro wired");
        assert_eq!(ds.led().candidates(), vec![0x00, 0x05]);
        assert_eq!(ds.lighting_tx().preferred(), Some(0x3F), "openrazer and SignalRGB outvote OpenRGB's 0x9F");
        let v4 = lookup(R, 0x0287).expect("BlackWidow V4");
        assert_eq!(v4.collections().len(), 2, "the V4's control collection moved at firmware 1.5");
    }

    /// openrazer razerkbd_driver.h: RAZER_BLACKWIDOW_CHROMA_WAIT_US 600, *_WIRELESS_WAIT_US 4900;
    /// razer_get_report_params puts the V3 Pro's wireless PID (0x025C) on the long one.
    #[test]
    fn reply_waits_follow_the_link() {
        assert_eq!(lookup(R, 0x024E).and_then(Keyboard::reply_wait_us), Some(600));
        assert_eq!(lookup(R, 0x025C).and_then(Keyboard::reply_wait_us), Some(4900));
        assert_eq!(lookup(R, 0x025A).and_then(Keyboard::reply_wait_us), Some(600), "the V3 Pro's wired PID");
    }
}
